// WatchTransferLockChanged subscribes to new "TransferLockChanged(bytes32,uint64)" logs and decodes them. Call Unsubscribe on the returned subscription when done.
func (c *IDiesisNamePolicyBinding) WatchTransferLockChanged(ctx context.Context, indexed ...[]any) (<-chan IDiesisNamePolicyTransferLockChangedEvent, event.Subscription, error) {
	if c.backend == nil {
		return nil, nil, fmt.Errorf("IDiesisNamePolicyBinding has no backend")
	}
	definition, err := c.event("TransferLockChanged(bytes32,uint64)")
	if err != nil {
		return nil, nil, err
	}
	count := 0
	for _, arg := range definition.Inputs {
		if arg.Indexed {
			count++
		}
	}
	if len(indexed) > count {
		return nil, nil, fmt.Errorf("too many indexed filters for %s", "TransferLockChanged(bytes32,uint64)")
	}
	queries := indexed
	queries = append([][]any{{definition.ID}}, queries...)
	topics, err := abi.MakeTopics(queries...)
	if err != nil {
		return nil, nil, err
	}
	logs := make(chan types.Log)
	upstream, err := c.backend.SubscribeFilterLogs(ctx, ethereum.FilterQuery{Addresses: []common.Address{c.address}, Topics: topics}, logs)
	if err != nil {
		return nil, nil, err
	}
	events := make(chan IDiesisNamePolicyTransferLockChangedEvent)
	subscription := event.NewSubscription(func(quit <-chan struct{}) error {
		defer upstream.Unsubscribe()
		defer close(events)
		for {
			select {
			case <-quit:
				return nil
			case <-ctx.Done():
				return ctx.Err()
			case err, ok := <-upstream.Err():
				if !ok {
					return nil
				}
				return err
			case log, ok := <-logs:
				if !ok {
					return nil
				}
				decoded, err := c.DecodeTransferLockChangedEvent(log)
				if err != nil {
					return err
				}
				select {
				case events <- decoded:
				case <-quit:
					return nil
				case <-ctx.Done():
					return ctx.Err()
				}
			}
		}
	})
	return events, subscription, nil
}

// DecodeNotAuthorizedError decodes a "NotAuthorized()" revert payload, including its selector.
func (c *IDiesisNamePolicyBinding) DecodeNotAuthorizedError(raw []byte) (out IDiesisNamePolicyNotAuthorizedError, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI error: %v", failure)
		}
	}()
	definition, err := c.customError("NotAuthorized()")
	if err != nil {
		return out, err
	}
	if len(raw) < 4 || !bytes.Equal(raw[:4], definition.ID[:4]) {
		return out, fmt.Errorf("error selector mismatch for %s", "NotAuthorized()")
	}
	values, err := definition.Inputs.Unpack(raw[4:])
	if err != nil {
		return out, err
	}
	if len(values) != 0 {
		return out, fmt.Errorf("error value count mismatch")
	}
	return out, nil
}

