// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisNamePolicyBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("NotAuthorized()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotAuthorizedError(raw)
	}
	if definition, err := c.customError("NotGuardian()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotGuardianError(raw)
	}
	if definition, err := c.customError("RecoveryDisabled()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeRecoveryDisabledError(raw)
	}
	if definition, err := c.customError("RecoveryNotReady()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeRecoveryNotReadyError(raw)
	}
	if definition, err := c.customError("TransferLocked()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeTransferLockedError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
